def parse_isotope_name_for_sort(name):
    """Parse isotope name to get element symbol and mass number for sorting."""
    name_lower = name.lower().strip()
    match = re.search(r'([a-zA-Z]+)-?(\d+)$', name_lower)
    if match:
        element = match.group(1)
        mass = int(match.group(2))
        z = ELEMENT_Z.get(element, 0)
        return (z, mass, name)
    return (0, 0, name)

def normalize_isotope_name(name):
    """Normalize isotope name for duplicate checking: lowercase, remove spaces/hyphens."""
    return name.lower().replace(' ', '').replace('-', '')

def load_atomic_densities():
    """Load atomic densities from file."""
    densities = {}
    if not os.path.exists(DENSITY_FILE):
        return densities
