        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split(':')
            if len(parts) < 3:
                continue
            isotope_name = parts[0].strip()
            try:
                density = float(parts[1].strip())
                atomic_mass = float(parts[2].strip())
            except ValueError:
                continue
