def parse_xs_file(filepath):
    """Parse a .xs file and return list of isotope data."""
    isotopes = []
    error_status = None
    validation_errors = []

    try:
        with open(filepath, 'r') as f:
            content = f.read()
    except Exception as e:
        return None, "read_error", [str(e)]

    lines = content.split('\n')
    current_isotope = None
    energy_data = []
    has_isotope_line = False

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if line.startswith('ISOTOPE:'):
            if current_isotope is not None:
                isotopes.append({'name': current_isotope, 'data': energy_data[:]})
            current_isotope = line[8:].strip()
            energy_data = []
            has_isotope_line = True
        elif line.startswith('ENERGY:'):
            rest = line[7:].strip()
            parts = rest.split()
            energy = None
            sigma_t = None
            sigma_a = None
            sigma_s = None

            for part in parts:
                if part.startswith('SIGMA_T:'):
                    try:
                        sigma_t = float(part[8:])
                    except ValueError:
                        sigma_t = None
                elif part.startswith('SIGMA_A:'):
                    try:
                        sigma_a = float(part[8:])
                    except ValueError:
                        sigma_a = None
                elif part.startswith('SIGMA_S:'):
                    try:
                        sigma_s = float(part[8:])
                    except ValueError:
                        sigma_s = None
                else:
                    try:
                        energy = float(part)
                    except ValueError:
                        energy = None

            if energy is not None and sigma_t is not None and sigma_a is not None and sigma_s is not None:
                energy_data.append((energy, sigma_t, sigma_a, sigma_s))
            else:
                validation_errors.append("invalid_format")

        if line.startswith('ENERGY:') and current_isotope is None:
            validation_errors.append("invalid_format")

    if current_isotope is not None:
        isotopes.append({'name': current_isotope, 'data': energy_data[:]})

    if not has_isotope_line:
        for line in lines:
            stripped = line.strip()
            if stripped and not stripped.startswith('#'):
                error_status = "invalid_format"
                break

