        if st < 0 or sa < 0 or ss < 0:
            errors.append("negative_cross_section")
            valid = False
            break

    for i, (st, sa, ss) in enumerate(zip(sigmas_t, sigmas_a, sigmas_s)):
        if abs(st - (sa + ss)) > 0.001:
            errors.append("cross_section_mismatch")
            valid = False

    for d in energy_data:
        for val in d[1:]:
            if val != val or abs(val) == float('inf'):
                errors.append("invalid_format")
                valid = False

    return valid, errors

def find_thermal_xs(data):
    target = THERMAL_ENERGY
    tolerance = THERMAL_TOLERANCE
    candidates = [(e, st) for e, st, sa, ss in data if abs(e - target) <= tolerance]
    if not candidates:
        return None, "insufficient_data"

    best = None
    best_dist = float('inf')
    for energy, sigma_t in candidates:
        dist = abs(energy - target)
        if dist < best_dist:
            best_dist = dist
            best = (energy, sigma_t)
        elif dist == best_dist and energy > best[0]:
            best = (energy, sigma_t)
    return best[1], None

def process_isotope(isotope_info, densities, seen_isotopes):
    name = isotope_info['name']
    normalized_name = normalize_isotope_name(name)

    # Check for duplicate first
    if normalized_name in seen_isotopes:
        return {
            'isotope': name, 'source_file': '', 'status': 'duplicate_isotope',
            'atomic_density_atoms_cm3': None, 'macroscopic_cross_section_cm_minus1': None,
            'reaction_rate_reactions_cm3_s': None, 'thermal_xs_barns': None,
            'validation_errors': []
        }
    seen_isotopes.add(normalized_name)

    # Check isotope name validity
    name_valid = bool(re.search(r'([a-zA-Z]+)-?(\d+)$', name.lower().strip()))

    result = {
        'isotope': name, 'source_file': '', 'status': 'valid',
        'atomic_density_atoms_cm3': None, 'macroscopic_cross_section_cm_minus1': None,
        'reaction_rate_reactions_cm3_s': None, 'thermal_xs_barns': None,
        'validation_errors': []
    }

    # Validate data
    is_valid, validation_errors = validate_isotope_data(isotope_info['data'])
    result['validation_errors'] = sorted(validation_errors)

    # Determine status based on priority
    # Priority order (lower number = higher priority): 
    # cross_section_mismatch=0, invalid_energy_ordering=1, negative_cross_section=2,
    # invalid_format=3, invalid_isotope_name=4
    error_priority = {
        'cross_section_mismatch': 0,
        'invalid_energy_ordering': 1,
        'negative_cross_section': 2,
        'invalid_format': 3,
        'invalid_isotope_name': 4,
    }

    # If name is invalid, it gets invalid_isotope_name status
    # But per spec priority, we should check if there are higher priority errors
    # Actually, re-reading: the priority list determines which status wins
    # invalid_isotope_name has priority 4, which is lower than cross_section_mismatch (0)
    # So if both exist, cross_section_mismatch wins

    status = 'valid'
    min_priority = float('inf')

    # Check validation errors first
    if validation_errors:
        for err in validation_errors:
            if err in error_priority:
                if error_priority[err] < min_priority:
                    min_priority = error_priority[err]
                    status = err

    # Check name validity (if name invalid, this is a candidate status)
    if not name_valid:
        if 'invalid_isotope_name' not in validation_errors:
            if error_priority.get('invalid_isotope_name', 5) < min_priority:
                min_priority = error_priority['invalid_isotope_name']
                status = 'invalid_isotope_name'

    result['status'] = status

    # Only do calculations if data is valid AND name is valid
    if is_valid and name_valid:
        thermal_xs, thermal_error = find_thermal_xs(isotope_info['data'])
        if thermal_error:
            result['status'] = thermal_error
            result['thermal_xs_barns'] = None
        else:
            raw_thermal_xs = thermal_xs
            result['thermal_xs_barns'] = round(raw_thermal_xs, 6)

            density_info = find_density_for_isotope(name, densities)
            if density_info is None:
                result['status'] = 'missing_density_data'
                result['atomic_density_atoms_cm3'] = None
                result['macroscopic_cross_section_cm_minus1'] = None
                result['reaction_rate_reactions_cm3_s'] = None
            else:
                density, atomic_mass = density_info
                N_unrounded = (density / atomic_mass) * ATOMIC_MASS_CONSTANT
                N_rounded = round(N_unrounded, 6)
                result['atomic_density_atoms_cm3'] = N_rounded
                sigma_cm2 = raw_thermal_xs * 1e-24
                macro_xs_unrounded = N_unrounded * sigma_cm2
                macro_xs_rounded = round(macro_xs_unrounded, 6)
                result['macroscopic_cross_section_cm_minus1'] = macro_xs_rounded
                reaction_rate = 1e14 * macro_xs_rounded
                result['reaction_rate_reactions_cm3_s'] = round(reaction_rate, 6)

    return result

def sort_xs_files(directory):
    xs_files = []
    if not os.path.exists(directory):
        return xs_files
    for root, dirs, files in os.walk(directory):
        for f in files:
            if f.endswith('.xs'):
                xs_files.append(os.path.join(root, f))
    xs_files.sort(key=lambda x: (x.count('/'), x), reverse=True)
    return xs_files

def main():
    if not os.path.exists(DATA_DIR):
        result = {"total_files": 0, "valid_files": 0, "invalid_files": 0,
                  "total_isotopes": 0, "valid_isotopes": 0, "invalid_isotopes": 0, "isotopes": []}
        write_output_atomic(result)
        return

    xs_files = sort_xs_files(DATA_DIR)
    densities = load_atomic_densities()
    seen_isotopes = set()

    all_isotopes = []
    total_files = 0
    valid_files = 0
    invalid_files = 0
    total_isotopes = 0
    valid_isotopes = 0
    invalid_isotopes = 0

    for filepath in xs_files:
        total_files += 1
        rel_path = os.path.relpath(filepath, DATA_DIR)
        isotopes, error_status, _ = parse_xs_file(filepath)

        if error_status == "read_error" or isotopes is None:
            invalid_files += 1
            continue

        valid_files += 1
        for iso_info in isotopes:
            total_isotopes += 1
            iso_result = process_isotope(iso_info, densities, seen_isotopes)
            iso_result['source_file'] = rel_path
            if iso_result['status'] == 'valid':
                valid_isotopes += 1
            else:
                invalid_isotopes += 1
            all_isotopes.append(iso_result)

    all_isotopes.sort(key=lambda x: parse_isotope_name_for_sort(x['isotope']), reverse=True)

    result = {
        "total_files": total_files, "valid_files": valid_files, "invalid_files": invalid_files,
        "total_isotopes": total_isotopes, "valid_isotopes": valid_isotopes, "invalid_isotopes": invalid_isotopes,
        "isotopes": all_isotopes
    }
    write_output_atomic(result)

def write_output_atomic(data):
    tmp_file = OUTPUT_FILE + '.tmp'
    with open(tmp_file, 'w') as f:
        json.dump(data, f, indent=2)
    os.rename(tmp_file, OUTPUT_FILE)

if __name__ == '__main__':
    main()
